#!/usr/bin/env node
// Writes munim-maps-vehicles' generated files from the models in
// packages/munim-maps-vehicles/usdz and /glb (made by make-vehicles.swift):
//
// - names.js / names.d.ts: VEHICLE_NAMES and the VehicleName type,
// - bundled/<name>.js (GLB), bundled/<name>.ios.js (USDZ) and
//   bundled/glb/<name>.js (GLB everywhere), each requiring only its own file,
//   with their .d.ts,
// - the name list in munim-maps' Swift `MunimVehicles`.
//
//   node scripts/vehicles/write-catalogue.mjs          # write
//   node scripts/vehicles/write-catalogue.mjs --check  # fail if out of date
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '../..')
const pkg = join(root, 'packages/munim-maps-vehicles')
const swift = join(root, 'packages/munim-maps/ios/Vehicles/MunimVehicles.swift')
const check = process.argv.includes('--check')

const usdz = readdirSync(join(pkg, 'usdz')).filter((f) => f.endsWith('.usdz')).map((f) => f.slice(0, -5)).sort()
const glb = readdirSync(join(pkg, 'glb')).filter((f) => f.endsWith('.glb')).map((f) => f.slice(0, -4)).sort()
if (usdz.join() !== glb.join()) {
  const missing = [...usdz.filter((n) => !glb.includes(n)).map((n) => `${n}.glb`), ...glb.filter((n) => !usdz.includes(n)).map((n) => `${n}.usdz`)]
  console.error(`munim-maps-vehicles: every model needs a .usdz and a .glb; missing ${missing.join(', ')}`)
  process.exit(1)
}
const names = usdz

const header = '// Generated by scripts/vehicles/write-catalogue.mjs. Do not edit.\n'
const files = new Map()

files.set(
  'names.js',
  `${header}module.exports.VEHICLE_NAMES = Object.freeze([\n${names.map((n) => `  '${n}',`).join('\n')}\n])\n`
)
files.set(
  'names.d.ts',
  `${header}/** Every model in munim-maps-vehicles. */\nexport type VehicleName =\n${names.map((n) => `  | '${n}'`).join('\n')}\n\n/** Every model name, sorted. */\nexport declare const VEHICLE_NAMES: readonly VehicleName[]\n`
)
const dts = `${header}/** The model as a bundled asset (a \`require()\`d file), for \`MapModel.source\`. */\ndeclare const source: number\nexport = source\n`
for (const n of names) {
  files.set(`bundled/${n}.js`, `${header}// GLB (Android and other platforms). Metro picks ${n}.ios.js on iOS.\nmodule.exports = require('../glb/${n}.glb')\n`)
  files.set(`bundled/${n}.ios.js`, `${header}// USDZ on iOS (SceneKit). For glTF on iOS (Mapbox's or Cesium's own models) use bundled/glb/${n}.\nmodule.exports = require('../usdz/${n}.usdz')\n`)
  files.set(`bundled/${n}.d.ts`, dts)
  files.set(`bundled/glb/${n}.js`, `${header}// GLB on every platform.\nmodule.exports = require('../../glb/${n}.glb')\n`)
  files.set(`bundled/glb/${n}.d.ts`, dts)
}

const swiftNames = `  public static let names: [String] = [\n${names.map((n) => `    "${n}",`).join('\n')}\n  ]`
const swiftSource = readFileSync(swift, 'utf8')
const swiftNext = swiftSource.replace(/ {2}public static let names: \[String\] = \[[\s\S]*?\n {2}\]/, swiftNames)
if (!swiftSource.includes('public static let names: [String] = [')) {
  console.error('MunimVehicles.swift has no `public static let names: [String] = [` list')
  process.exit(1)
}

let stale = []
for (const [file, text] of files) {
  const path = join(pkg, file)
  if (!existsSync(path) || readFileSync(path, 'utf8') !== text) stale.push(file)
}
// Generated files for models that no longer exist.
const bundledDir = join(pkg, 'bundled')
const extra = []
for (const dir of [bundledDir, join(bundledDir, 'glb')]) {
  if (!existsSync(dir)) continue
  for (const f of readdirSync(dir, { withFileTypes: true })) {
    if (!f.isFile()) continue
    const rel = join(dir, f.name).slice(pkg.length + 1)
    if (!files.has(rel)) extra.push(rel)
  }
}
const swiftStale = swiftNext !== swiftSource

if (check) {
  if (stale.length || extra.length || swiftStale) {
    console.error(
      `munim-maps-vehicles: generated files are out of date (${[...stale, ...extra, ...(swiftStale ? ['MunimVehicles.swift'] : [])].slice(0, 5).join(', ')}…); run node scripts/vehicles/write-catalogue.mjs`
    )
    process.exit(1)
  }
  console.log(`munim-maps-vehicles: ${names.length} models, generated files up to date`)
  process.exit(0)
}

for (const rel of extra) rmSync(join(pkg, rel))
for (const file of stale) {
  const path = join(pkg, file)
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, files.get(file))
}
if (swiftStale) writeFileSync(swift, swiftNext)
console.log(`munim-maps-vehicles: ${names.length} models; wrote ${stale.length} files, removed ${extra.length}${swiftStale ? ', updated MunimVehicles.swift' : ''}`)
